# POST /api/sheets/{sheetId}/claims/{claimId}/defer — defer an OPEN claim (body {until, user}) until a
# date after the sheet's today. Until the sheet's today reaches that date the claim counts in no total,
# is not overdue, cannot be settled and is left unbound by a statement; from that day on it is an OPEN
# claim like any other. Refused (400) when the date does not parse or is not after today, the claim is
# not OPEN or not on the sheet, or its due-by falls in a closed period; nothing is stored then. A stored
# deferral is recorded in the audit file as CLAIM_DEFERRED.
validate:
  class: net.officefloor.hq.app.claim.ValidateDefer
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkDefer
checkDefer:
  class: net.officefloor.hq.app.claim.CheckDefer
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyDefer
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimDeferred
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/claims/{claimId}/lock — open a claim's editor (body {user}): locks the claim
# for every other user until the editor is saved or cancelled (unlock) or the sheet's today changes.
# Refused (400) for a viewer, a claim not on the sheet, one that is not a DRAFT, one whose due-by falls in a
# closed period, or one another user has locked; nothing is stored then. Records nothing in the audit file.
validate:
  class: net.officefloor.hq.app.claim.ValidateLock
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkDraft
checkDraft:
  class: net.officefloor.hq.app.claim.CheckClaimDraft
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyLock
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateDefer {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody DeferRequest request, Out<DeferInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String text = request == null || request.until() == null ? "" : request.until().trim();
        try {
            body.set(new DeferInput(LocalDate.parse(text), request.user()));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + text);
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Refuses deferring a claim that is not OPEN, or to a date that is not after the sheet's today. */
public class CheckDefer {
    public void check(@Val DeferInput input, @Val Claim claim, SheetStore sheets) throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new InvalidSheetException("Only an OPEN claim can be deferred");
        }
        LocalDate today = sheets.today(claim.getSheetId());
        if (!input.until().isAfter(today)) {
            throw new InvalidSheetException("A claim can only be deferred to a date after " + today);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Stores the OPEN claim deferred until the date; refused when another user moved it on first. */
public class ApplyDefer {
    public void apply(@Val DeferInput input, @Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (!store.defer(claim, input.until())) {
            throw new InvalidSheetException("Only an OPEN claim can be deferred");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a stored deferral: CLAIM_DEFERRED sheet=<id> by=<user> person=<name> amount=<0.00>
 *  date=<yyyy-mm-dd> number=<n> until=<yyyy-mm-dd>. */
public class AuditClaimDeferred {
    public void audit(@Val DeferInput input, @Val Claim claim, @Val Rollup before, PersonStore people, Audit audit,
            RollupService rollups) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_DEFERRED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber())
                + " until=" + input.until());
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
