31	  const claims = useClaims(sheet);
32	  const rates = useRates(sheet);
33	  const settings = useSettings(sheet).data;
34	  const floor = floorOf(settings);
35	  const today = useSheetToday(sheet);
36	  const periods = usePeriods(sheet);
37	  const [fields, setFields] = useState<Fields>(EMPTY);
38	  // The claim whose editor is open (and locked by this user), kept in the URL so it outlives a re-load
39	  // of the sheet; this person's form edits it when it is one of theirs.
40	  const [editingId, setEditing] = useEditingClaim();
41	  const editingClaim = (claims.data ?? []).find((c) => c.id === editingId && c.personId === person.id);
42	  const editing = editingClaim?.id;
43	  const [reasons, setReasons] = useState<Record<number, string>>({});
44	  const [targets, setTargets] = useState<Record<number, string>>({});
45	  const [deferDates, setDeferDates] = useState<Record<number, string>>({});
46	  const [redates, setRedates] = useState<Record<number, string>>({});
47	  const [splitAmounts, setSplitAmounts] = useState<Record<number, string>>({});
48	  const people = usePeople(sheet);
49	  const [selected, setSelected] = useSelectedClaims();
50	  const queryClient = useQueryClient();
51	  const base = `/api/sheets/${encodeURIComponent(sheet)}`;
52	
53	  const save = useMutation({
54	    mutationFn: (f: Fields) =>
55	      editing !== undefined
56	        ? putJson<Claim>(`${base}/claims/${editing}`, { ...f, user })
57	        : postJson<Claim>(`${base}/people/${person.id}/claims`, { ...f, user }),
58	    onSuccess: async () => {
59	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
60	      setFields(EMPTY);
61	      setEditing(undefined);
62	    },
63	  });
64	
65	  const submit = useSubmitOnce(save);
66	
67	  // Opening a claim's editor locks it for every other user; the server refuses a claim that cannot be
68	  // edited or that another user has locked, and the error shows on that claim.
69	  const lock = useMutation({
70	    mutationFn: (c: Claim) => postJson<Claim>(`${base}/claims/${c.id}/lock`, { user }),
71	    onSuccess: (_, c) => {
72	      if (editingId !== undefined && editingId !== c.id) release(editingId);
73	      setEditing(c.id);
74	      setFields({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' });
75	    },
76	  });
77	  // Cancelling an editor releases its lock.
78	  const release = (id: number) => {
79	    void postJson<Claim>(`${base}/claims/${id}/unlock`, { user }).catch(() => undefined);
80	  };
81	
82	  // The server refuses a change the claim's status does not allow; the error shows on that claim.
83	  const move = useMutation({
84	    mutationFn: (m: StatusChange) =>
85	      postJson<Claim>(`${base}/claims/${m.id}/status`, { status: m.status, user, review: m.review ?? false, reason: m.reason ?? '' }),
86	    onSuccess: async (_, m) => {
87	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
88	      if (m.review) setReasons((r) => ({ ...r, [m.id]: '' }));
89	    },
90	  });
91	  const moveTo = (id: number, status: ClaimStatus, review?: { reason: string }) => {
92	    move.reset();
93	    lock.reset();
94	    reassign.reset();
95	    resettle.reset();
96	    defer.reset();
97	    proof.reset();
98	    split.reset();
99	    redate.reset();
100	    move.mutate({ id, status, review: review !== undefined, reason: review?.reason });
101	  };
102	
103	  // Moving a claim re-reads the people too: both people's figures follow it.
104	  const reassign = useMutation({
105	    mutationFn: (r: Reassign) => postJson<Claim>(`${base}/claims/${r.id}/reassign`, { to: r.to, user }),
106	    onSuccess: async (_, r) => {
107	      await Promise.all([
108	        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
109	        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
110	      ]);
111	      setTargets((t) => ({ ...t, [r.id]: '' }));
112	    },
113	  });
114	  const reassignTo = (id: number) => {
115	    move.reset();
116	    lock.reset();
117	    reassign.reset();
118	    resettle.reset();
119	    defer.reset();
120	    proof.reset();
121	    split.reset();
122	    redate.reset();
123	    reassign.mutate({ id, to: targets[id] ?? '' });
124	  };
125	  // A steward re-settling a SETTLED claim freezes it again at today's figure.
126	  const resettle = useMutation({
127	    mutationFn: (id: number) => postJson<Claim>(`${base}/claims/${id}/resettle`, { user }),
128	    onSuccess: async () => {
129	      await Promise.all([
130	        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
131	        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
132	      ]);
133	    },
134	  });
135	  const resettleClaim = (id: number) => {
136	    move.reset();
137	    lock.reset();
138	    reassign.reset();
139	    resettle.reset();
140	    defer.reset();
141	    proof.reset();
142	    split.reset();
143	    redate.reset();
144	    resettle.mutate(id);
145	  };
146	  // Deferring an OPEN claim until a date after today takes it out of every figure until then.
147	  const defer = useMutation({
148	    mutationFn: (d: { id: number; until: string }) =>
149	      postJson<Claim>(`${base}/claims/${d.id}/defer`, { until: d.until, user }),
150	    onSuccess: async () => {
151	      await Promise.all([
152	        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
153	        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
154	      ]);
155	    },
156	  });
157	  const deferClaim = (id: number) => {
158	    move.reset();
159	    lock.reset();
160	    reassign.reset();
161	    resettle.reset();
162	    defer.reset();
163	    proof.reset();
164	    split.reset();
165	    redate.reset();
166	    defer.mutate({ id, until: (deferDates[id] ?? '').trim() });
167	  };
168	  // A proof raises the claim's proofs count by one; not on a SETTLED or VOID claim.
169	  const proof = useMutation({
170	    mutationFn: (id: number) => postJson<Claim>(`${base}/claims/${id}/proof`, { user }),
171	    onSuccess: async () => {
172	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
173	    },
174	  });
175	  const addProof = (id: number) => {
176	    move.reset();
177	    lock.reset();
178	    reassign.reset();
179	    resettle.reset();
180	    defer.reset();
181	    proof.reset();
182	    split.reset();
183	    redate.reset();
184	    proof.mutate(id);
185	  };
186	  // Splitting an amount off an OPEN claim lists a new OPEN claim with it; both people's figures follow.
187	  const split = useMutation({
188	    mutationFn: (d: { id: number; amount: string }) =>
189	      postJson<Claim>(`${base}/claims/${d.id}/split`, { amount: d.amount, user }),
190	    onSuccess: async (_, d) => {
191	      await Promise.all([
192	        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
193	        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
194	      ]);
195	      setSplitAmounts((a) => ({ ...a, [d.id]: '' }));
196	    },
197	  });
198	  const splitClaim = (id: number) => {
199	    move.reset();
200	    lock.reset();
201	    reassign.reset();
202	    resettle.reset();
203	    defer.reset();
204	    proof.reset();
205	    split.reset();
206	    redate.reset();
207	    split.mutate({ id, amount: (splitAmounts[id] ?? '').trim() });
208	  };
209	  // A steward re-dates an OPEN or PENDING claim; its due-by, and so its period (and per-period number), stay as they are.
210	  const redate = useMutation({
211	    mutationFn: (d: { id: number; date: string }) =>
212	      postJson<Claim>(`${base}/claims/${d.id}/redate`, { date: d.date, user }),
213	    onSuccess: async (_, d) => {
214	      await Promise.all([
215	        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
216	        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
217	      ]);
218	      setRedates((a) => ({ ...a, [d.id]: '' }));
219	    },
220	  });
221	  const redateClaim = (id: number) => {
222	    move.reset();
223	    lock.reset();
224	    reassign.reset();
225	    resettle.reset();
226	    defer.reset();
227	    proof.reset();
228	    split.reset();
229	    redate.mutate({ id, date: (redates[id] ?? '').trim() });
230	  };
231	  // The refusal of the last status change, move, re-settle, deferral, proof, split or re-dating of the claim, as the server gave it; null when none.
232	  const refusal = (id: number) => {
233	    const error =
234	      move.isError && move.variables?.id === id
235	        ? move.error
236	        : reassign.isError && reassign.variables?.id === id
237	          ? reassign.error
238	          : resettle.isError && resettle.variables === id
239	            ? resettle.error
240	            : defer.isError && defer.variables?.id === id
241	              ? defer.error
242	              : proof.isError && proof.variables === id
243	                ? proof.error
244	                : split.isError && split.variables?.id === id
245	                  ? split.error
246	                  : redate.isError && redate.variables?.id === id
247	                    ? redate.error
248	                    : lock.isError && lock.variables?.id === id
249	                      ? lock.error
250	                      : null;
251	    if (error === null) return null;
252	    return error instanceof HttpError && error.reason ? `${error.reason}.` : 'The change was refused.';
253	  };
254	
255	  const set = (key: keyof Fields) => (e: ChangeEvent<HTMLInputElement>) => {
256	    setFields({ ...fields, [key]: e.target.value });
257	    save.reset();
258	  };
259	  const open = (c: Claim) => {
260	    save.reset();
261	    move.reset();
262	    lock.reset();
263	    reassign.reset();
264	    resettle.reset();
265	    defer.reset();
266	    proof.reset();
267	    split.reset();
268	    redate.reset();
269	    lock.mutate(c);
270	  };
271	  const cancel = () => {
272	    save.reset();
273	    lock.reset();
274	    if (editing !== undefined) release(editing);
275	    setEditing(undefined);
276	    setFields(EMPTY);
277	  };
278	
279	  // An editor still open when the sheet is shown again fills the form with its claim.
280	  useEffect(() => {
281	    if (editingClaim) {
282	      setFields({ amount: editingClaim.amount, date: editingClaim.date, note: editingClaim.note, corrects: editingClaim.corrects ?? '' });
283	    }
284	  }, [editing]);
285	
286	  return (
287	    <td>
288	      <ul>
289	        {(claims.data ?? [])
290	          .filter((c) => c.personId === person.id)
291	          .map((c) => (
292	            <li key={c.id} data-testid={`claim-row-${c.id}`}>
293	              <input
294	                type="checkbox"
295	                data-testid="claim-select"
296	                aria-label="Select claim"
297	                checked={selected.includes(c.id)}
298	                onChange={(e) => setSelected(e.target.checked ? [...selected, c.id] : selected.filter((id) => id !== c.id))}
299	              />{' '}
300	              <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
301	              <span data-testid="claim-amount">{c.amount}</span>{' '}
302	              <span data-testid="claim-date">{c.date}</span>{' '}
303	              <span data-testid="claim-note">{c.note}</span>{' '}
304	              <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
305	              <span data-testid="claim-period">{periodOf(periods.data, c.dueBy)?.name ?? ''}</span>{' '}
306	              <span data-testid="claim-due">{claimDue(c, rates.data, person.grades, floor, lateOf(settings, today))}</span>{' '}
307	              <span data-testid="claim-due-by">{dueBy(c)}</span>{' '}
308	              <span data-testid="claim-overdue">{overdue(c, today) ? 'yes' : 'no'}</span>{' '}
309	              <span data-testid="claim-status">{c.status}</span>{' '}
310	              <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
311	              <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
312	              <span data-testid="claim-deferred">{c.deferred ? 'yes' : 'no'}</span>{' '}
313	              <span data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</span>{' '}
314	              <span data-testid="claim-split-from">{c.splitFrom ?? ''}</span>{' '}
315	              <span data-testid="claim-late-entry">{c.lateEntry ? 'yes' : 'no'}</span>{' '}
316	              <button type="button" data-testid="claim-open" disabled={move.isPending} onClick={() => moveTo(c.id, 'OPEN')}>
317	                Open
318	              </button>{' '}
319	              <button type="button" data-testid="claim-settle" disabled={move.isPending} onClick={() => moveTo(c.id, 'SETTLED')}>
320	                Settle
321	              </button>{' '}
322	              <button type="button" data-testid="claim-void" disabled={move.isPending} onClick={() => moveTo(c.id, 'VOID')}>
323	                Void
324	              </button>{' '}
325	              <button
326	                type="button"
327	                data-testid="claim-resettle"
328	                disabled={resettle.isPending}
329	                onClick={() => resettleClaim(c.id)}
330	              >
331	                Re-settle
332	              </button>{' '}
333	              <button
334	                type="button"
335	                data-testid="claim-approve"
336	                disabled={move.isPending}
337	                onClick={() => moveTo(c.id, 'SETTLED', { reason: '' })}
338	              >
339	                Approve
340	              </button>{' '}
341	              <input
342	                data-testid="claim-reject-reason"
343	                placeholder="Reason"
344	                aria-label="Reject reason"
345	                value={reasons[c.id] ?? ''}
346	                onChange={(e) => {
347	                  setReasons({ ...reasons, [c.id]: e.target.value });
348	                  if (move.variables?.id === c.id) move.reset();
349	                }}
350	              />{' '}
351	              <button
352	                type="button"
353	                data-testid="claim-reject"
354	                disabled={move.isPending}
355	                onClick={() => moveTo(c.id, 'OPEN', { reason: reasons[c.id] ?? '' })}
356	              >
357	                Reject
358	              </button>{' '}
359	              <select
360	                data-testid="claim-reassign-to"
361	                aria-label="Move to"
362	                value={targets[c.id] ?? ''}
363	                onChange={(e) => {
364	                  setTargets({ ...targets, [c.id]: e.target.value });
365	                  if (reassign.variables?.id === c.id) reassign.reset();
366	                }}
367	              >
368	                <option value="">Move to…</option>
369	                {(people.data ?? [])
370	                  .filter((p) => p.id !== person.id)
371	                  .map((p) => (
372	                    <option key={p.id} value={String(p.id)}>
373	                      {p.name}
374	                    </option>
375	                  ))}
376	              </select>{' '}
377	              <button
378	                type="button"
379	                data-testid="claim-reassign"
380	                disabled={reassign.isPending}
381	                onClick={() => reassignTo(c.id)}
382	              >
383	                Move
384	              </button>{' '}
385	              <input
386	                data-testid="claim-defer-date"
387	                type="date"
388	                aria-label="Defer until"
389	                value={deferDates[c.id] ?? ''}
390	                onChange={(e) => {
391	                  setDeferDates({ ...deferDates, [c.id]: e.target.value });
392	                  if (defer.variables?.id === c.id) defer.reset();
393	                }}
394	              />{' '}
395	              <button type="button" data-testid="claim-defer" disabled={defer.isPending} onClick={() => deferClaim(c.id)}>
396	                Defer
397	              </button>{' '}
398	              <input
399	                data-testid="claim-date-new"
400	                type="date"
401	                aria-label="New date"
402	                value={redates[c.id] ?? ''}
403	                onChange={(e) => {
404	                  setRedates({ ...redates, [c.id]: e.target.value });
405	                  if (redate.variables?.id === c.id) redate.reset();
406	                }}
407	              />{' '}
408	              <button type="button" data-testid="claim-redate" disabled={redate.isPending} onClick={() => redateClaim(c.id)}>
409	                Re-date
410	              </button>{' '}
411	              <span data-testid="claim-proofs">{c.proofs ?? 0}</span>{' '}
412	              <button type="button" data-testid="claim-proof" disabled={proof.isPending} onClick={() => addProof(c.id)}>
413	                Add proof
414	              </button>{' '}
415	              <input
416	                data-testid="claim-split-amount"
417	                placeholder="Split off"
418	                aria-label="Amount to split off"
419	                inputMode="decimal"
420	                value={splitAmounts[c.id] ?? ''}
421	                onChange={(e) => {
422	                  setSplitAmounts({ ...splitAmounts, [c.id]: e.target.value });
423	                  if (split.variables?.id === c.id) split.reset();
424	                }}
425	              />{' '}
426	              <button type="button" data-testid="claim-split" disabled={split.isPending} onClick={() => splitClaim(c.id)}>
427	                Split
428	              </button>{' '}
429	              <button type="button" data-testid="claim-edit" disabled={lock.isPending} onClick={() => open(c)}>
430	                Edit
431	              </button>
432	              {editing === c.id && (
433	                <button type="button" data-testid="claim-cancel" onClick={cancel}>
434	                  Cancel
435	                </button>
436	              )}
437	              {refusal(c.id) !== null && (
438	                <span data-testid="claim-error" role="alert">
439	                  {' '}
440	                  {refusal(c.id)}
441	                </span>
442	              )}
443	              <ol data-testid="claim-log">
444	                {(c.log ?? []).map((line, i) => (
445	                  <li key={i} data-testid="claim-log-line">
446	                    {line}
447	                  </li>
448	                ))}
449	              </ol>
450	            </li>
451	          ))}
452	      </ul>
453	      <form
454	        data-testid="claim-form"
455	        onSubmit={(e) => {
456	          e.preventDefault();
457	          submit(fields);
458	        }}
459	      >
460	        <input data-testid="claim-form-amount" placeholder="Amount" inputMode="decimal" value={fields.amount} onChange={set('amount')} />
461	        <input data-testid="claim-form-date" placeholder="Date (yyyy-mm-dd)" value={fields.date} onChange={set('date')} />
462	        <input data-testid="claim-form-note" placeholder="Note" value={fields.note} onChange={set('note')} />
463	        <input
464	          data-testid="claim-form-corrects"
465	          placeholder="Corrects claim no."
466	          inputMode="numeric"
467	          value={fields.corrects}
468	          onChange={set('corrects')}
469	        />
470	        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
471	          {editing !== undefined ? 'Save claim' : 'Add claim'}
472	        </button>
473	        {save.isError && (
474	          <span data-testid="claim-form-error" role="alert">
475	            {' '}
476	            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The claim was refused.'}
477	          </span>
478	        )}
479	      </form>
480	    </td>
481	  );
482	}
483	
484	export const contributions = [
485	  PersonColumnHeads.fill({ order: 20, Component: ClaimsHead }),
486	  PersonColumns.fill({ order: 20, Component: PersonClaims }),
487	];
