# POST /api/sheets/{sheetId}/claims/{claimId}/proof — raise a claim's proofs count by one (body {user}).
# Refused (400) for a SETTLED or VOID claim, a claim not on the sheet, or one whose due-by falls in a
# closed period; nothing is stored then. A stored proof is recorded in the audit file as CLAIM_PROOF_ADDED.
validate:
  class: net.officefloor.hq.app.claim.ValidateProof
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyProof
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimProof
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

/** Body of a claim's proof, as sent: who adds it. */
public record ProofRequest(String user) {
}
package net.officefloor.hq.app.claim;

/** A validated proof: who adds it. */
public record ProofInput(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateProof {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ProofRequest request, Out<ProofInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(new ProofInput(request == null ? null : request.user()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
